   for(int i=0;i<3;i++){tiers[i].interactable=valid&&d.seasonWins>=RewardHubRules.Threshold(i)&&!d.seasonClaimed[i];tiers[i].transform.Find("Label").GetComponent<TMP_Text>().text=d.seasonClaimed[i]?L.V("common.claimed"):d.seasonWins>=RewardHubRules.Threshold(i)?L.V("common.claim"):L.V("common.locked");}
